"""Offline unit tests for the Portfolio Size correction logic."""

import json
import os
import tempfile
import unittest
from unittest.mock import MagicMock

from py_attio.portfolio import (
    PORTFOLIO_SIZE_ATTR,
    aggregate_locations,
    first_number,
    update_portfolio_sizes,
)


def _location(company_id, sf):
    values = {}
    if company_id:
        values["company"] = [{"target_record_id": company_id}]
    if sf is not None:
        values["sf_occupied"] = [{"value": sf}]
    return {"id": {"record_id": "loc"}, "values": values}


def _company(company_id, name, portfolio):
    values = {"name": [{"value": name}]}
    if portfolio is not None:
        values[PORTFOLIO_SIZE_ATTR] = [{"value": portfolio}]
    return {"id": {"record_id": company_id}, "values": values}


class TestFirstNumber(unittest.TestCase):
    def test_shapes(self):
        self.assertEqual(first_number({"a": [{"value": 5}]}, "a"), 5.0)
        self.assertEqual(first_number({"a": [3]}, "a"), 3.0)
        self.assertIsNone(first_number({"a": [{"value": None}]}, "a"))
        self.assertIsNone(first_number({"a": []}, "a"))
        self.assertIsNone(first_number({}, "a"))
        self.assertIsNone(first_number({"a": [{"value": "junk"}]}, "a"))


class TestAggregateLocations(unittest.TestCase):
    def test_sums_per_company_and_counts_unknowns(self):
        client = MagicMock()
        client.paginate_records.return_value = iter(
            [
                _location("c1", 100),
                _location("c1", 50),
                _location("c1", None),
                _location("c2", None),
                _location(None, 10),
            ]
        )
        agg = aggregate_locations(client, "locations", 500)
        self.assertEqual(agg["c1"], {"sum": 150.0, "locations": 3, "with_sf": 2})
        self.assertEqual(agg["c2"], {"sum": 0.0, "locations": 1, "with_sf": 0})
        self.assertNotIn(None, agg)


class TestUpdatePortfolioSizes(unittest.TestCase):
    def _client(self, locations, companies):
        client = MagicMock()
        client.paginate_records.return_value = iter(locations)
        client.list_records.return_value = {"data": companies}
        return client

    def test_updates_only_mismatches(self):
        locations = [
            _location("c1", 100),  # c1 expected 100, stored 5 -> update
            _location("c2", 200),  # c2 expected 200, stored 200 -> skip
            _location("c3", None),  # c3 no sf data -> skipped by default
        ]
        companies = [
            _company("c1", "Wrong Co", 5),
            _company("c2", "Right Co", 200),
            _company("c3", "NoData Co", 999),
        ]
        client = self._client(locations, companies)
        with tempfile.TemporaryDirectory() as tmp:
            audit = os.path.join(tmp, "audit.jsonl")
            code = update_portfolio_sizes(
                client,
                "companies",
                "locations",
                page_size=500,
                batch_size=100,
                dry_run=False,
                write_zero_when_unknown=False,
                per_update_sleep_s=0,
                audit_file=audit,
            )
            self.assertEqual(code, 0)
            self.assertEqual(client.update_record.call_count, 1)
            args = client.update_record.call_args.args
            self.assertEqual(args[1], "c1")
            self.assertEqual(
                args[2]["data"]["values"][PORTFOLIO_SIZE_ATTR], [{"value": 100.0}]
            )
            with open(audit) as f:
                actions = [json.loads(line)["action"] for line in f]
            self.assertIn("updated", actions)
            self.assertIn("skipped_no_sf_data", actions)

    def test_dry_run_never_writes(self):
        client = self._client([_location("c1", 100)], [_company("c1", "Co", None)])
        code = update_portfolio_sizes(
            client,
            "companies",
            "locations",
            page_size=500,
            batch_size=100,
            dry_run=True,
            write_zero_when_unknown=False,
            per_update_sleep_s=0,
        )
        self.assertEqual(code, 0)
        client.update_record.assert_not_called()

    def test_null_portfolio_gets_set(self):
        client = self._client([_location("c1", 100)], [_company("c1", "Co", None)])
        update_portfolio_sizes(
            client,
            "companies",
            "locations",
            page_size=500,
            batch_size=100,
            dry_run=False,
            write_zero_when_unknown=False,
            per_update_sleep_s=0,
        )
        client.update_record.assert_called_once()

    def test_update_failure_returns_nonzero(self):
        client = self._client([_location("c1", 100)], [_company("c1", "Co", 5)])
        client.update_record.side_effect = RuntimeError("boom")
        code = update_portfolio_sizes(
            client,
            "companies",
            "locations",
            page_size=500,
            batch_size=100,
            dry_run=False,
            write_zero_when_unknown=False,
            per_update_sleep_s=0,
        )
        self.assertEqual(code, 1)

    def test_missing_company_counts_as_failure(self):
        client = self._client([_location("c1", 100)], [])  # batch returns nothing
        code = update_portfolio_sizes(
            client,
            "companies",
            "locations",
            page_size=500,
            batch_size=100,
            dry_run=False,
            write_zero_when_unknown=False,
            per_update_sleep_s=0,
        )
        self.assertEqual(code, 1)

    def test_write_zero_when_unknown_flag(self):
        client = self._client([_location("c1", None)], [_company("c1", "Co", 999)])
        update_portfolio_sizes(
            client,
            "companies",
            "locations",
            page_size=500,
            batch_size=100,
            dry_run=False,
            write_zero_when_unknown=True,
            per_update_sleep_s=0,
        )
        client.update_record.assert_called_once()


if __name__ == "__main__":
    unittest.main()
